	private void assertCases(String fixture, Supplier<TupleExpr> expression, List<Case> cases) {
		System.out.printf("repeat-context-environment fixture=%s enabled=%s forceRootGeneric=%s bareFragments=%s%n",
				fixture, System.getProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "<default>"),
				System.getProperty("rdf4j.lmdb.nativeQueryEngine.forceRootGeneric", "<default>"),
				System.getProperty("rdf4j.lmdb.bareFragments.enabled", "<default>"));
		List<Mode> modes = fixture.equals("original-root-only")
				? List.of(new Mode("generic", generic), new Mode("native-enabled", nativeStrategy))
				: List.of(new Mode("generic", generic),
						new Mode("native-generic-only", nativeStrategy.genericOnlyView()),
						new Mode("native-enabled", nativeStrategy));
		SoftAssertions softly = new SoftAssertions();
		for (Case test : cases) {
			for (Mode mode : modes) {
				List<Map<String, Value>> actual = observe(fixture, test.label(), mode, expression.get(), test.input());
				softly.assertThat(actual)
						.as("%s / %s / %s", fixture, test.label(), mode.label())
						.containsExactlyInAnyOrderElementsOf(test.expected());
			}
		}
		softly.assertAll();
	}

	private List<Map<String, Value>> observe(String fixture, String label, Mode mode, TupleExpr root,
			BindingSet input) {
		for (TupleExpr tuple : tuples(root)) {
			if (!fixture.equals("original-root-only") || tuple == root) {
				tuple.setRuntimeTelemetryEnabled(true);
				tuple.setExecutionSummaryEnabled(true);
			}
		}
		QueryEvaluationStep step = mode.strategy().precompile(root, context);
		List<TupleExpr> observed = tuples(root);
		Map<TupleExpr, Long> before = new IdentityHashMap<>();
		for (TupleExpr tuple : observed) {
			tuple.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH, null);
			tuple.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, null);
			before.put(tuple, Math.max(0L, tuple.getLongMetricActual("nativeInvocationsActual")));
		}
		List<Map<String, Value>> rows = new ArrayList<>();
		try (var result = step.evaluate(input)) {
			while (result.hasNext()) {
				Map<String, Value> row = new HashMap<>();
				result.next().forEach(binding -> row.put(binding.getName(), binding.getValue()));
				rows.add(Map.copyOf(row));
			}
		}
		String selected = step instanceof LmdbNativePhysicalPlan physical ? physical.nativePhysicalPlan()
				: "<step did not expose a native physical plan>";
		System.out.printf("repeat-context fixture=%s case=%s mode=%s input=%s selected=%s rows=%s%n",
				fixture, label, mode.label(), input, selected, rows);
		for (TupleExpr tuple : observed) {
			long delta = Math.max(0L, tuple.getLongMetricActual("nativeInvocationsActual")) - before.get(tuple);
			System.out.printf("repeat-context-node fixture=%s case=%s mode=%s node=%s@%x delta=%d "
					+ "plannedKind=%s plannedPlan=%s path=%s runtime=%s%n", fixture, label, mode.label(),
					tuple.getSignature(), System.identityHashCode(tuple), delta,
					tuple.getStringMetricPlanned(TelemetryMetricNames.PLANNED_EXECUTION_KIND),
					tuple.getStringMetricPlanned("nativePhysicalPlan"),
					tuple.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH),
					tuple.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN));
		}
		return rows;
	}

	private static List<TupleExpr> tuples(TupleExpr root) {
		List<TupleExpr> tuples = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof TupleExpr tuple) {
					tuples.add(tuple);
				}
				super.meetNode(node);
			}
		});
		return tuples;
	}

	private static StatementPattern repeatedPattern() {
		return pattern(Var.of("g"));
	}

	private static StatementPattern pattern(Var context) {
		return new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("g"),
				Var.of("predicate", P, true, true), Var.of("x"), context);
	}

	private static TupleExpr repeatedJoin() {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setDeclaredBindingNames(Set.of("t"));
		values.setBindingSets(List.of(binding("t", A), binding("t", A), binding("t", B), binding("t", C)));
		Filter filter = new Filter(values, new Compare(Var.of("x"), Var.of("t")));
		filter.setConditionBindingScope(Filter.ConditionBindingScope.retain(Set.of("x", "t")));
		return new Join(repeatedPattern(), filter);
	}

	private static TupleExpr originalRepeatedJoin() {
		StatementPattern pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("g"),
				Var.of("predicate", ORIGINAL_CONTEXT_P, true, true), Var.of("x"), Var.of("g"));
		BindingSetAssignment values = new BindingSetAssignment();
		values.setDeclaredBindingNames(Set.of("t"));
		values.setBindingSets(List.of(binding("t", ORIGINAL_A), binding("t", ORIGINAL_B), binding("t", ORIGINAL_C)));
		Filter filter = new Filter(values, new Compare(Var.of("x"), Var.of("t")));
		filter.setConditionBindingScope(Filter.ConditionBindingScope.retain(Set.of("x", "t")));
		return new Join(pattern, filter);
	}

	private static MapBindingSet binding(String name, Value value) {
		MapBindingSet result = new MapBindingSet();
		result.addBinding(name, value);
		return result;
	}

	private static MapBindingSet pair(String first, Value firstValue, String second, Value secondValue) {
		MapBindingSet result = binding(first, firstValue);
		result.addBinding(second, secondValue);
		return result;
	}

	private static Map<String, Value> row(String first, Value firstValue, String second, Value secondValue) {
		return Map.of(first, firstValue, second, secondValue);
	}

	private static Map<String, Value> row(String first, Value firstValue, String second, Value secondValue,
			String third, Value thirdValue) {
		return Map.of(first, firstValue, second, secondValue, third, thirdValue);
	}
